std::string text(const std::string& english) {
    std::string translated = text(english.c_str());
    if (translated != english || currentLanguage != Language::Russian) return translated;

    struct Prefix { const char* english; const char* russian; };
    static const Prefix prefixes[] = {
        {"Opened chest: ", "Открыт сундук: "}, {"Unlocked chest: ", "Открыт запертый сундук: "},
        {"Picked up ", "Подобрано: "}, {"Killed ", "Убито: "},
        {"You can't remove cursed ", "Нельзя снять проклятый предмет: "},
        {"Ghost: ", "Призрак: "}, {"Wandmaker: ", "Создатель жезлов: "},
        {"Blacksmith: ", "Кузнец: "}, {"Imp: ", "Бес: "}, {"Shopkeeper: ", "Торговец: "},
        {"Rat King: ", "Король крыс: "}, {"Ascended to floor ", "Подъём на этаж "},
        {"You talk to ", "Вы говорите с: "}, {"Added ", "Добавлено: "},
        {"Teleported to floor ", "Перемещение на этаж "}
    };
    for (const Prefix& prefix : prefixes) {
        const std::string source(prefix.english);
        if (english.compare(0, source.size(), source) == 0) {
            return std::string(prefix.russian) + text(english.substr(source.size()));
        }
    }
    return english;
}

